    private static func base(_ key: String) -> String {
        key.replacingOccurrences(of: #"\[\d+\]"#, with: "", options: .regularExpression)
    }
    static func label(_ key: String) -> FieldLabel {
        let components = key.split(separator: ".").map(String.init)
        let leaf = base(components.last ?? key)
        if key.range(of: #"[А-Яа-яЁё]"#, options: .regularExpression) != nil {
            return FieldLabel(title: key, explanation: "Сведения об устройстве.", known: true)
        }
        let known = catalog[leaf]
        let generic: String
        if leaf.hasPrefix("PortControllerIrqCnt") { generic = "Счётчик прерываний контроллера порта" }
        else if leaf.hasPrefix("PortController") { generic = "Служебный показатель контроллера порта" }
        else if leaf.hasPrefix("Ra") && leaf.dropFirst(2).allSatisfy(\.isNumber) { generic = "Параметр модели батареи Ra" }
        else if leaf.hasSuffix("NotificationType") { generic = "Тип системного уведомления" }
        else if leaf.hasPrefix("Accumulated"), let translated = catalog[String(leaf.dropFirst(11))] { generic = "Накопленное значение: " + translated.0.lowercased() }
        else { generic = "Служебный параметр Apple" }
        let indices = (components.last ?? "").replacingOccurrences(of: leaf, with: "")
        let parents = components.dropLast().map { part in
            let b = base(part)
            return (catalog[b]?.0 ?? "Служебные данные") + part.replacingOccurrences(of: b, with: "")
        }
        let title = (parents + [(known?.0 ?? generic) + indices]).joined(separator: " › ")
        return FieldLabel(title: title, explanation: known?.1 ?? "Внутреннее диагностическое поле Apple. Точная расшифровка или единицы не подтверждены; значение показано без интерпретации.", known: known != nil)
    }
    private static let bytes: Set<String> = ["TotalDiskCapacity", "TotalDataCapacity", "TotalDataAvailable", "TotalSystemCapacity", "TotalSystemAvailable", "AmountDataAvailable", "AmountDataReserved", "AmountRestoreAvailable", "size_in_bytes"]
    private static let flags: Set<String> = ["PasswordProtected", "SIM1IsEmbedded", "SIM2IsEmbedded", "HostAttached", "TrustedHostAttached", "ActivationStateAcknowledged", "TelephonyCapability", "Uses24HourClock", "BatteryInstalled", "HasBattery", "FullyCharged", "IsCharging", "ExternalConnected", "ExternalChargeCapable", "AtCriticalLevel", "IsWireless", "Built-In", "built-in", "SupportsExtendedBatteryState", "IOMatchedAtBoot"]
    static func value(_ raw: String, for key: String) -> String {
        let leaf = base(key.split(separator: ".").last.map(String.init) ?? key)
        if flags.contains(leaf) {
            if ["true", "yes", "1"].contains(raw.lowercased()) { return "Да" }
            if ["false", "no", "0"].contains(raw.lowercased()) { return "Нет" }
        }
        if bytes.contains(leaf), let n = Double(raw), n >= 0, n < Double(Int64.max) {
            let units = [(1e12, "ТБ"), (1e9, "ГБ"), (1e6, "МБ"), (1e3, "КБ")]
            for (scale, unit) in units where n >= scale { return String(format: "%.2f", locale: Locale(identifier: "ru_RU"), n / scale) + " " + unit }
            return raw + " байт"
        }
        // Only these top-level fields have verified units in the battery reader.
        if key == "Temperature", let n = Double(raw), n > 0 { return String(format: "%.2f °C", locale: Locale(identifier: "ru_RU"), n / 100) }
        if key == "Voltage", let n = Double(raw), n > 0 { return String(format: "%.3f В", locale: Locale(identifier: "ru_RU"), n / 1000) }
        if leaf == "ActivationState", raw == "Activated" { return "Активировано" }
        if leaf == "smart_status", raw == "Verified" { return "Проверено (SMART)" }
        if ["DeviceClass", "device_minorType"].contains(leaf) { return ["Keyboard": "Клавиатура", "Magic Trackpad": "Трекпад Magic", "Mouse": "Мышь", "Headphones": "Наушники"][raw] ?? raw }
        return raw
    }
    static func matches(_ query: String, key: String, raw: String) -> Bool {
        let info = label(key)
        return query.isEmpty || [key, raw, info.title, info.explanation, value(raw, for: key)].contains { $0.localizedCaseInsensitiveContains(query) }
    }
    static func export(_ record: TechnicalRecord) throws -> Data {
        let encoder = JSONEncoder(); encoder.dateEncodingStrategy = .iso8601
        var object = try JSONSerialization.jsonObject(with: encoder.encode(record)) as! [String: Any]
        var translated: [String: [String: [String: String]]] = [:]
        for (section, fields) in record.sections {
            translated[section] = fields.reduce(into: [:]) { result, item in
                let info = label(item.key)
                result[item.key] = ["name_ru": info.title, "description_ru": info.explanation, "display_value_ru": value(item.value, for: item.key)]
            }
        }
        object["translations"] = translated
        return try JSONSerialization.data(withJSONObject: object, options: [.prettyPrinted, .sortedKeys])
    }
